export const COUNTRY_INFO = Object.fromEntries(RAW.trim().split('\n').map((line) => {
  const [id, capital, languages, currency, dish, bestPlace, bestWhy, ...facts] = line.split('|');
  return [id, { capital, languages, currency, dish, bestPlace, bestWhy, facts }];
}));

export const infoFor = (id) => COUNTRY_INFO[id] || null;
